// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2019, "8-9", [{"author":"А. Пиперски","question":"<em>— Саша, у тебя есть красная ручка? — Откуда? Я же не учитель. — Ну _____________.</em>","choices":["<em>едва ли</em>","<em>много ли</em>","<em>мало ли</em>","<em>долго ли</em>","<em>вдруг ли</em>."],"key":"В","review":["Красная ручка","Саша говорит, что он не учитель и поэтому не обязан иметь красную ручку. Собеседник возражает: из этого ещё ничего не следует.","«Ну мало ли» выражает мысль, что ручка всё-таки могла оказаться у Саши. Так и заканчивается реплика."]},{"author":"Б. Иомдин","question":"Что объединяет бельё, мусор, грибы, бумаги и файлы?","choices":["ящик","бак","ведро","таз","корзина."],"key":"Д","review":["Что кладут в корзину","Подумай, куда складывают бельё и грибы. Оба предмета можно положить в одну и ту же ёмкость.","Бумаги и мусор выбрасывают в корзину, а удалённые файлы попадают в компьютерную «Корзину». Это слово объединяет все пять примеров."]},{"author":"Б. Иомдин","question":"Какая пара устроена не так, как другие?","choices":["<em>удивляться — удивиться</em>","<em>кривляться — кривиться</em>","<em>вдохновляться — вдохновиться</em>","<em>возобновляться — возобновиться</em>","<em>появляться — появиться</em>."],"key":"Б","review":["Видовые пары глаголов","«Удивляться — удивиться», «вдохновляться — вдохновиться», «возобновляться — возобновиться» и «появляться — появиться» различаются видом.","«Кривляться» и «кривиться» могут оба описывать незавершённое действие. Они различаются значением, поэтому такой видовой пары не образуют."]},{"author":"Б. Иомдин и М. Иомдин","question":"Расставьте приставки в этом предложении: <em>Я ...лагал, что ...лагаться на него нельзя, и ...лагаю не ...лагать на него всю ответственность.</em>","choices":["<em>по-, по-, по-, воз-</em>","<em>по-, воз-, пред-, по-</em>","<em>предпо-, по-, пред-, воз-</em>","<em>предпо-, по-, по-, на-</em>","<em>по-, по-, предпо-, на-</em>."],"key":"В","review":["Приставки в предложении","Нужны глаголы со значениями «думал», «доверять», «советую» и «переложить обязанность». Сопоставь их с общей частью «-лаг-».","Получаются «предполагал», «полагаться», «предлагаю» и «возлагать». В варианте В даны четыре фрагмента перед «-лаг-»."]},{"author":"Б. Иомдин","question":"<em>Ах, картина жизни праздной: долгий город безобразный, образ родины всерьёз!\nНе узнала, не забыла, билась в судороге, любила, выгоняла на мороз…</em>\nКакое слово в этом отрывке из стихотворения Бахыта Кенжеева читается нестандартно?","choices":["<em>праздной</em>","<em>безобразный</em>","<em>всерьёз</em>","<em>в судороге</em>","<em>на мороз.</em>"],"key":"Г","review":["Ритм у Кенжеева","Прочитай соседние части по восемь слогов, например «Не узнала, не забыла». При отчётливом произнесении «билась в судороге, любила» получается девять.","Чтобы сохранить ритм, «судороге» произносится с пропуском одного безударного гласного, примерно «в су́дорге». В остальных словах такого сокращения не требуется."]},{"author":"О. Подлесская","question":"Про вещь, проданную на аукционе, говорят, что <em>она ушла …</em> .","choices":["<em>с молотка</em>","<em>с верстака</em>","<em>с прилавка</em>","<em>с витрины</em>","<em>с ярмарки</em>."],"key":"А","review":["Вещь с аукциона","Аукционист фиксирует продажу традиционным ударом молотка. Название предмета закрепилось в устойчивой фразе.","Про вещь, купленную на торгах, говорят «ушла с молотка»."]},{"author":"Л. Фёдорова","question":"Рота королевских мушкетёров под командованием д’Артаньяна называлась «серые мушкетёры» из-за цвета коней. А рота гвардейцев кардинала — «чёрные мушкетёры». Какой масти были кони гвардейцев кардинала?","choices":["гнедые","саврасые","вороные","буланые","пегие."],"key":"В","review":["Масть коней","В вопросе сказано, что цвет коней отразился в названиях двух рот. У «чёрных мушкетёров» нужны чёрные лошади.","Чёрную масть называют вороной. Подходит вариант «вороные»."]},{"author":"А. Анисимов","question":"Сколько прилагательных в следующем предложении? <em>Сидя в приёмной, я по-быстрому написал докладную, которую просил дежурный.</em>","choices":["ни одного","одно","два","три","четыре."],"key":"А","review":["Части речи в предложении","«В приёмной» означает «в комнате», «докладную» называют запиской, «дежурный» называет человека. В этом предложении эти слова отвечают на вопросы к существительным.","«По-быстрому» — наречие, «сидя» — деепричастие. Прилагательных, обозначающих признаки существительных, в предложении нет."]},{"author":"М. Рубинштейн","question":"Н. Н. Носов описывает, как его маленький внук Игорь увидел по телевизору выступление музыкального ансамбля: «Игорь спросил, как называется этот инструмент, и недоверчиво смеялся, когда я сказал: [...]. Наверно, думал, что [...] — это какое-то смешное слово вроде <em>драндулет</em>». (Н. Н. Носов. Повесть о моём друге Игоре) Какой это был музыкальный инструмент?","choices":["аккордеон","бандура","валторна","гитара","домбра."],"key":"Б","review":["Музыкальный инструмент","Дед называет инструмент, а ребёнок воспринимает незнакомое слово как смешное. Сравни слова по звучанию с «драндулет».","Носов пишет, что это была «бандура». Её необычное для ребёнка звучание и вызывает смешок."]},{"author":"Л. Фёдорова","question":"В каком из примеров значение подчёркнутого глагола существенно отличается от остальных?\n1) <em>Лисица видит сыр; лисицу сыр <u>пленил</u>.</em> (И. А. Крылов)\n2) <em>Достали нот, баса, альта, две скрипки\nИ сели на лужок под липки, ―\n<u>Пленять</u> своим искусством свет.</em> (И. А. Крылов)\n3) <em>Там королевич мимоходом <u>пленяет</u> грозного царя.</em> (А. С. Пушкин)\n4) <em>Сюда гусары отпускные\nСпешат явиться, прогреметь,\nБлеснуть, <u>пленить</u> и улететь.</em> (А. С. Пушкин)","choices":["в первом","во втором","в третьем","в четвёртом","во всех примерах значение глаголов одно и то же."],"key":"В","review":["Глагол «пленить»","Сыр пленил лисицу, музыканты пленяют свет своим искусством, а гусары хотят пленить присутствующих. Здесь имеются в виду восхищение и влечение.","Королевич пленяет царя буквально, берёт его в плен. Это действие отличается от остальных случаев."]},{"author":"И. Рубанов","question":"<em>Всё на благотворительность — ничего ...!</em> Какое слово, поставленное вместо многоточия, сделает фразу двусмысленной?","choices":["<em>вам</em>","<em>ему</em>","<em>им</em>","<em>себе</em>","<em>тебе</em>."],"key":"Г","review":["Фраза о пожертвовании","Если все средства идут на благотворительность, после тире можно противопоставить «ничего себе», то есть говорящий ничего не оставляет для себя.","То же сочетание «Ничего себе!» выражает удивление. Два чтения возникают только у варианта «себе»."]},{"author":"С. Дьяченко","question":"Даны вологодские диалектные слова <em>хрясту́чий</em>, <em>хря́пчий</em>, <em>ху́дкий</em>, <em>хухринова́тый</em> и их значения в перепутанном порядке:\n1) покрытый пупырышками; 2) отличающийся низким качеством;\n3) быстро и легко густеющий; 4) человек, который разрезает пироги на свадьбе.\nВыберите вариант, в котором значения всех слов перечислены в правильном порядке.","choices":["4, 3, 2, 1","3, 4, 2, 1","3, 1, 2, 4","2, 3, 1, 4","2, 1, 4, 3."],"key":"Б","review":["Вологодские слова","«Худкий» связан с «худой» в значении «плохой», это определение 2. В «хряпчий» можно узнать глагол о разрезании, подходит тот, кто разрезает пироги, определение 4.","В официальном соответствии «хрястучий» — быстро и легко густеющий, а «хухриноватый» — покрытый пупырышками. Получается 3, 4, 2, 1."]},{"author":"Л. Фёдорова","question":"Обстоятельства времени могут выражаться предложными сочетаниями с существительным <em>утро</em>. С какими из предлогов — <em>с</em>, <em>на</em>, <em>до</em>, <em>по</em>, <em>под</em> — слово <em>утро</em> образует наречия в слитном написании?","choices":["с каждым из предлогов","только с предлогом <em>с</em>","только с предлогом <em>на</em>","только с предлогом <em>по</em>","только с предлогами <em>на</em> и <em>по</em>."],"key":"Д","review":["Когда пишут слитно","Слово «утро» с предлогами часто остаётся отдельным: «с утра», «до утра», «под утро».","Слитно пишутся наречия «наутро» и «поутру». Они образованы с «на» и «по»."]},{"author":"А. Сомин","question":"Антон придумывал слова, отвечающие некоторому требованию. В его список, получившийся очень маленьким, попало слово <em>ноты</em>, а слово <em>ворона</em> могло бы попасть, если бы требование было не таким жёстким. Какое из этих слов не попало в список Антона?","choices":["<em>ивы</em>","<em>Лион</em>","<em>Илья</em>","<em>пони</em>","<em>ведьмы</em>."],"key":"Г","review":["Два слова в одном","«Ноты» делится на «но» и «ты», то есть на служебное слово и личное местоимение. «Ворона» тоже заканчивается на «она», но «вор» — существительное.","Получаются «и вы», «ли он», «иль я» и «ведь мы». «Пони» такой пары не даёт."]},{"author":"О. Душкина","question":"В каком предложении слово <em>сервис</em> употреблено ошибочно?\n1. <em>Вот бы ещё сельский сервис был приветливее и расписание автобусов удобнее.\n2. Сервис, конечно, оставлял желать лучшего, но самое главное — мы были вместе.\n3. Сервис в этой сфере начал развиваться только в последние годы и уже достиг высокого уровня.\n4. Вот шведский сервис с фабрики «Густавсберг», специально созданный для известного ресторана.</em>","choices":["в первом","во втором","в третьем","в четвёртом","во всех предложениях слово употреблено правильно."],"key":"Г","review":["Два слова про рестораны","«Сервис» означает обслуживание. Так можно сказать об удобстве услуг, работе сотрудников или уровне обслуживания.","Предмет с фабрики посуды, созданный для ресторана, — «сервиз». В четвёртом предложении нужна буква З вместо С."]},{"author":"Л. Фёдорова","question":"Словацкий и русский — родственные языки. Что означают словацкие слова: podchod, nadjazd, vzostup, nástup?","choices":["посадка, подъём, эстакада, подземный переход","подъём, эстакада, посадка, подземный переход","подземный переход, эстакада, подъём, посадка","подземный переход, посадка, подъём, эстакада","посадка, эстакада, подземный переход, подъём."],"key":"В","review":["Слова по-словацки","В «podchod» слышится путь под чем-то, а в «nadjazd» — проезд над чем-то. Это подземный переход и эстакада.","«Vzostup» близко к «восступить», означает подъём. «Nástup» значит посадка. Порядок соответствует варианту В."]},{"author":"Л. Фёдорова","question":"Жители какой из этих исторических областей, как считается, отличались способностью говорить кратко?","choices":["Аркадии","Аттики","Дакии","Лаконики","Македонии."],"key":"Г","review":["Жители и краткая речь","Вспомни слово «лаконичный». Это характеристика речи, в которой мысль передана коротко.","Название связано с Лаконикой, областью со Спартой. Спартанцам приписывали привычку отвечать кратко."]},{"author":"С. Сай","question":"Даны прилагательные <em>латвийский</em>, <em>литовский</em>, <em>эстонский</em>. Какие из них являются общепринятыми русскими названиями государственных языков этих стран?","choices":["<em>латвийский</em> и <em>литовский</em>","только <em>литовский</em>","<em>литовский</em> и <em>эстонский</em>","только <em>эстонский</em>","все три."],"key":"В","review":["Страны и языки","Правильно «литовский язык» и «эстонский язык». Их названия совпадают с прилагательными к названиям стран.","Государственный язык Латвии принято называть «латышским». Из списка подходят «литовский» и «эстонский»."],"reviewedEdition":true,"keyNote":"В исходном вопросе среди возможных обозначений латышского языка могло подразумеваться редкое «латвийский». В интерактивной редакции спрашивается об общепринятых названиях государственных языков. Реестр балтийских языков Ю. Корякова: lingvarium.org/eurasia/IE/balt.shtml, aH2."},{"author":"Е. Муравенко","question":"Разные слова <em>горе</em> и <em>гора</em> в форме предложного падежа единственного числа пишутся одинаково: <em>о горе</em>. Даны ещё пять пар таких слов. У какой пары слов существуют и другие одинаково пишущиеся падежные формы?","choices":["<em>о дне</em>","<em>об угле</em>","<em>об ухе</em>","<em>о стрелке</em>","<em>о погоне</em>."],"key":"Г","review":["Совпадающие формы","«О стрелке» может быть о стрелке прибора или о человеке, который стреляет. Это разные существительные «стрелка» и «стрелок».","У них совпадают и другие записи: «дать стрелку задание» и «передвинуть стрелку». Совпадение сохраняется также в написании «стрелки»."]},{"author":"Л. Фёдорова","question":"Какое из ряда существительных совсем не имеет форм множественного числа?","choices":["<em>благо</em>","<em>зло</em>","<em>добро</em>","<em>чудо</em>","<em>яство</em>."],"key":"В","review":["Слова во множественном числе","Можно сказать «блага», «чудеса», «яства». Есть и выражение «меньшее из зол», где «зол» — форма множественного числа.","«Добро» в значении блага или имущества употребляется в единственном числе. Обычной формы множественного у него нет."]},{"author":"Е. Бикмаев","question":"В корне какого из перечисленных слов можно наблюдать чередование <em>ч</em>/<em>щ</em>?","choices":["<em>вещь</em>","<em>речь</em>","<em>течь</em>","<em>плач</em>","<em>ночь</em>."],"key":"Д","review":["Два согласных в корне","Сравни «ночь» и старое слово «нощь». Оба означают время суток, но согласные в конце различаются.","Та же Щ сохранилась в слове «всенощный». Это пример Ч и Щ в одном историческом корне."]},{"author":"Е. Бикмаев","question":"В какой из этих пословиц и поговорок одно из слов употреблено не в литературной форме?","choices":["<em>В здоровом теле — здоровый дух.</em>","<em>У кого что болит, тот о том и говорит.</em>","<em>Всё полезно, что в рот полезло.</em>","<em>Доброе слово лечит, а злое калечит.</em>","<em>Лук от семи недуг.</em>"],"key":"Д","review":["Форма в пословице","Один недуг, несколько недугов. В литературной речи после «семи» нужна именно форма «недугов».","Поговорка сохранила форму «недуг», которая рифмуется со словом «лук»."]},{"author":"Е. Бикмаев","question":"Дима загадал форму глагола в первом лице единственного числа и сказал, что она оканчивается на -<em>лю</em>. Маша спросила: «А в неопределённой форме этот глагол оканчивается на - <em>еть</em>?» — «Нет». — «Значит, на -<em>ить</em>». — «Да». — «Тогда я смогу отгадать, какая буква стоит перед -<em>ить</em> в неопределённой форме этого глагола, не больше чем с … попыток» — и она верно рассуждает. Со скольких же попыток?","choices":["трёх","четырёх","пяти","шести","семи."],"key":"Г","review":["Угадать букву глагола","Формы от «любить», «купить», «ловить», «кормить» и «разграфить» дают «люблю», «куплю», «ловлю», «кормлю» и «разграфлю». Здесь возможны Б, П, В, М, Ф.","Л может уже входить в основу, как в «пилить — пилю». Всего шесть букв, поэтому достаточно шести попыток."]},{"author":"Л. Фёдорова","question":"В каком из примеров слова не входят в одну и ту же пословицу или поговорку?","choices":["<em>Киев — дядька</em>","<em>Рим — дорога</em>","<em>Тверь — самовар</em>","<em>Киев — язык</em>","во всех примерах пары слов входят в одну и ту же пословицу или поговорку."],"key":"В","review":["Города в поговорках","Сверь пары с известными текстами: «в Киеве дядька», «все дороги ведут в Рим», «язык до Киева доведёт».","С самоваром ездят в поговорке в Тулу, а не в Тверь. Пары «Тверь — самовар» нет."]},{"author":"Б. Иомдин","question":"В одной статье написано, что низкий уровень аллергенности «встречается у пушистых сибиряков и балинезийских кошек, а также ориенталов, которые бывают и коротко, и длинношёрстными». Что пропустил журналист в этом примере?","choices":["тире","дефис","запятую","скобки","в этом примере всё правильно."],"key":"Б","review":["Общее слово в прилагательных","В сочетании перечислены предметы двух видов: короткошёрстные и длинношёрстные. У обоих прилагательных одинаковый конец.","Если этот конец убрать у первого слова, нужно отметить пропуск дефисом: «и коротко-, и длинношёрстными»."]},{"author":"А. Пиперски","question":"В четырёхтомном «Словаре русского языка» под редакцией А. П. Евгеньевой, который известен как «Малый академический словарь», толкуются названия русских букв. Какое из этих толкований противоречит трём из четырёх остальных?","choices":["Е. Название шестой буквы русского алфавита","И. Название девятой буквы русского алфавита","О. Название пятнадцатой буквы русского алфавита","У. Название двадцатой буквы русского алфавита","Э. Название тридцать первой буквы русского алфавита."],"key":"Д","review":["Порядок букв в словаре","Если считать Ё отдельной буквой, И — десятая, О — шестнадцатая, У — двадцать первая. Названные в вопросе позиции этих трёх букв на единицу меньше, то есть Ё не считали.","Но тридцать первая позиция Э получается, только если учесть Ё как отдельную букву. Поэтому именно толкование Э противоречит трём другим."]},{"author":"И. Иткин","question":"Перед вами — названия пяти глав повести Василия Аксёнова «Мой дедушка — памятник»: четыре подлинных и одно, которого в книге на самом деле нет. Какое название вымышлено?","choices":["ГЛАВА 1, из которой доносятся до нас звуки раннего детства Геннадия Стратофонтова и скрежет учительских ручек, выводивших в его дневнике многочисленные пятёрки.","ГЛАВА 3, в которой слышится пение кота и тявканье «Ржавой акулы».","ГЛАВА 5, которая не оставляет сомнений, что ночная прогулка по морскому берегу способна доставить истинное удовольствие даже миллиардеру.","ГЛАВА 8, которая на своём убедительном примере показывает, что голоса логики и разума порой могут потонуть в неистовом шуме сбитой с толку толпы.","ГЛАВА 9, в которой впервые как средство связи появляется ультразвук, вновь слышится пение кота и музыка ночного Оук-порта."],"key":"В","review":["Заголовок главы","Проверить догадку можно по авторским заголовкам глав Аксёнова. Названия про кота, «Ржавую акулу» и Оук-порт действительно встречаются в книге.","Пятая глава обещает читателю услышать отголоски прошлых столетий. Заголовок о прогулке миллиардера вымышлен."]},{"author":"А. Анисимов","question":"Когда сборная этой страны заняла второе место на крупном турнире по футболу, жители в шутку предложили переименовать страну: мол, в этом случае в следующий раз она точно станет чемпионом. Эта страна — … .","choices":["Аргентина","Бразилия","Голландия","Франция","Хорватия."],"key":"А","review":["Название и медаль","За второе место вручают серебро, за первое — золото. Ищи страну, имя которой связано с серебром.","«Аргентина» напоминает латинское «argentum» — серебро. В шутке заменяют серебряное имя на золотое, чтобы пожелать победы."]},{"author":"М. Рубинштейн","question":"Один школьник пересказывал повесть, написанную в XIX веке. Вот как, по его мнению, обращаются некоторые персонажи повести друг к другу: «Ваше сияние», «Ваше благородство», «Ваша святость», «Ваше высокомерие». Сколько ошибок в обращениях сделал школьник?","choices":["одну","две","три","четыре","ни одной."],"key":"Г","review":["Старинные обращения","Сравни «Ваше сияние» со «Ваше сиятельство», «Ваше благородство» со «Ваше благородие», «Ваша святость» со «Ваше Святейшество». Уже три формы искажены.","«Ваше высокомерие» тоже не титул. Существуют, например, «Ваше высокоблагородие» и «Ваше высокопревосходительство». Ошибки во всех четырёх обращениях."]},{"author":"А. Пиперски","question":"Даны названия шести подряд идущих букв русского алфавита, записанные корейским письмом: 페, 에르, 에스, 테, 우, 에프. Какие это буквы?","choices":["А, Б, В, Г, Д, Е","Д, Е, Ё, Ж, З, И","К, Л, М, Н, О, П","П, Р, С, Т, У, Ф","Ъ, Ы, Ь, Э, Ю, Я."],"key":"Г","review":["Буквы корейским письмом","В первых формулах можно узнать названия «пэ», «эр», «эс», «тэ». Корейская запись может добавлять гласные после непривычных согласных сочетаний.","Далее идут «у» и «эф». От П до Ф получаем подряд П, Р, С, Т, У, Ф."]}], {"year":2019,"grade":"8-9","tasksFile":"8-9.pdf","answersFile":"8-9-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2019-1.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
